BehaviorModuleOutput LaneChangeInterface::plan()
{
  autoware_utils::ScopedTimeTrack st(__func__, *getTimeKeeper());
  resetPathCandidate();
  resetPathReference();

  auto output = module_type_->generateOutput();
  path_reference_ = std::make_shared<PathWithLaneId>(output.reference_path);

  stop_pose_ = module_type_->getStopPose();

  const auto & lane_change_debug = module_type_->getDebugData();
  for (const auto & [uuid, data] : lane_change_debug.collision_check_objects_after_approval) {
    const auto color = data.is_safe ? ColorName::GREEN : ColorName::RED;
    setObjectsOfInterestData(data.current_obj_pose, data.obj_shape, color);
  }

  updateSteeringFactorPtr(output);
  if (module_type_->isAbortState()) {
    const auto candidate = planCandidate();
    path_candidate_ = std::make_shared<PathWithLaneId>(candidate.path_candidate);
    updateRTCStatus(
      std::numeric_limits<double>::lowest(), std::numeric_limits<double>::lowest(), true,
      State::ABORTING);
  } else {
    const auto path =
      assignToCandidate(module_type_->getLaneChangePath(), module_type_->getEgoPosition());
    const auto is_registered = std::any_of(
      rtc_interface_ptr_map_.begin(), rtc_interface_ptr_map_.end(),
      [&](const auto & rtc) { return rtc.second->isRegistered(uuid_map_.at(rtc.first)); });

    if (!is_registered) {
      updateRTCStatus(
        path.start_distance_to_path_change, path.finish_distance_to_path_change, true,
        State::WAITING_FOR_EXECUTION);
    } else {
      updateRTCStatus(
        path.start_distance_to_path_change, path.finish_distance_to_path_change,
        !is_rtc_force_activated(), State::RUNNING);
    }
  }

  set_longitudinal_planning_factor(output.path);

  return output;
}

BehaviorModuleOutput NormalLaneChange::generateOutput()
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);
  if (!status_.is_valid_path) {
    RCLCPP_DEBUG(logger_, "No valid path found. Returning previous module's path as output.");
    insert_stop_point(get_current_lanes(), prev_module_output_.path);
    return prev_module_output_;
  }

  auto output = prev_module_output_;
  if (isAbortState() && abort_path_) {
    output.path = abort_path_->path;
    insert_stop_point(get_current_lanes(), output.path);
  } else {
    output.path = status_.lane_change_path.path;

    const auto found_extended_path = extendPath();
    if (found_extended_path) {
      output.path = utils::combinePath(output.path, *found_extended_path);
    }
    output.reference_path = getReferencePath();

    if (isStopState()) {
      const auto current_velocity = getEgoVelocity();
      const auto current_dist = calcSignedArcLength(
        output.path.points, output.path.points.front().point.pose.position, getEgoPosition());
      const auto stop_dist =
        -(current_velocity * current_velocity / (2.0 * planner_data_->parameters.min_acc));
      set_stop_pose(stop_dist + current_dist, output.path, "incoming rear object");
    } else {
      insert_stop_point(get_target_lanes(), output.path);
    }
  }

  extendOutputDrivableArea(output);

  const auto turn_signal_info =
    get_turn_signal(getEgoPose(), status_.lane_change_path.info.lane_changing_end);
  const auto current_seg_idx = planner_data_->findEgoSegmentIndex(output.path.points);
  output.turn_signal_info = planner_data_->turn_signal_decider.overwrite_turn_signal(
    output.path, getEgoPose(), current_seg_idx, prev_module_output_.turn_signal_info,
    turn_signal_info, planner_data_->parameters.ego_nearest_dist_threshold,
    planner_data_->parameters.ego_nearest_yaw_threshold);

  set_signal_activation_time(
    output.turn_signal_info.turn_signal.command != turn_signal_info.turn_signal.command);

  return output;
}

void NormalLaneChange::insert_stop_point(
  const lanelet::ConstLanelets & lanelets, PathWithLaneId & path, const bool is_waiting_approval)
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);
  if (lanelets.empty()) {
    return;
  }

  const auto & route_handler = getRouteHandler();

  if (route_handler->getNumLaneToPreferredLane(lanelets.back()) == 0) {
    return;
  }

  const auto & current_lanes = get_current_lanes();
  const auto is_current_lane = lanelets.front().id() == current_lanes.front().id() &&
                               lanelets.back().id() == current_lanes.back().id();

  // if input is not current lane, we can just insert the points at terminal.
  if (!is_current_lane) {
    if (common_data_ptr_->transient_data.next_dist_buffer.min < calculation::eps) {
      return;
    }
    const auto arc_length_to_stop_pose = motion_utils::calcArcLength(path.points) -
                                         common_data_ptr_->transient_data.next_dist_buffer.min;
    set_stop_pose(arc_length_to_stop_pose, path, "next lc terminal");
    return;
  }

  insert_stop_point_on_current_lanes(path, is_waiting_approval);
}

int RouteHandler::getNumLaneToPreferredLane(
  const lanelet::ConstLanelet & lanelet, const Direction direction) const
{
  if (exists(preferred_lanelets_, lanelet)) {
    return 0;
  }

  if ((direction == Direction::NONE) || (direction == Direction::RIGHT)) {
    const auto right_opt =
      autoware::experimental::lanelet2_utils::right_lanelets(lanelet, routing_graph_ptr_);
    if (right_opt.has_value()) {
      int num{0};
      const auto & right_lanes = *right_opt;
      for (const auto & right : right_lanes) {
        num--;
        if (exists(preferred_lanelets_, right)) {
          return num;
        }
      }
    }
  }

  if ((direction == Direction::NONE) || (direction == Direction::LEFT)) {
    const auto left_opt =
      autoware::experimental::lanelet2_utils::left_lanelets(lanelet, routing_graph_ptr_);
    if (left_opt.has_value()) {
      const auto & left_lanes = *left_opt;
      int num = 0;
      for (const auto & left : left_lanes) {
        num++;
        if (exists(preferred_lanelets_, left)) {
          return num;
        }
      }
    }
  }

  return 0;  // TODO(Horibe) check if return 0 is appropriate.
}

bool exists(const std::vector<LaneletPrimitive> & primitives, const int64_t & id)
{
  for (const auto & p : primitives) {
    if (p.id == id) {
      return true;
    }
  }
  return false;
}

std::optional<lanelet::ConstLanelets> right_lanelets(
  const lanelet::ConstLanelet & lanelet,
  const lanelet::routing::RoutingGraphConstPtr & routing_graph)
{
  lanelet::ConstLanelets lanelets;
  auto right_lane = right_lanelet(lanelet, routing_graph);
  // If the right lane doesn't exist at the first place.
  if (!right_lane.has_value()) {
    return std::nullopt;
  }
  // If the right lane exists.
  while (right_lane.has_value()) {
    lanelets.push_back(right_lane.value());
    right_lane = right_lanelet(right_lane.value(), routing_graph);
  }
  return lanelets;
}

std::optional<lanelet::ConstLanelet> right_lanelet(
  const lanelet::ConstLanelet & lanelet, const lanelet::routing::RoutingGraphConstPtr routing_graph)
{
  if (const auto right_lane = routing_graph->right(lanelet)) {
    // lane changeable
    return *right_lane;
  }
  if (const auto adjacent_right_lane = routing_graph->adjacentRight(lanelet)) {
    return *adjacent_right_lane;
  }
  return std::nullopt;
}

std::optional<lanelet::ConstLanelets> left_lanelets(
  const lanelet::ConstLanelet & lanelet,
  const lanelet::routing::RoutingGraphConstPtr & routing_graph)
{
  lanelet::ConstLanelets lanelets;
  auto left_lane = left_lanelet(lanelet, routing_graph);
  // If the left lane doesn't exist at the first place.
  if (!left_lane.has_value()) {
    return std::nullopt;
  }
  // If the left lane exists.
  while (left_lane.has_value()) {
    lanelets.push_back(left_lane.value());
    left_lane = left_lanelet(left_lane.value(), routing_graph);
  }
  return lanelets;
}

std::optional<lanelet::ConstLanelet> left_lanelet(
  const lanelet::ConstLanelet & lanelet, const lanelet::routing::RoutingGraphConstPtr routing_graph)
{
  if (const auto left_lane = routing_graph->left(lanelet)) {
    // lane changeable
    return *left_lane;
  }
  if (const auto adjacent_left_lane = routing_graph->adjacentLeft(lanelet)) {
    return *adjacent_left_lane;
  }
  return std::nullopt;
}

const lanelet::ConstLanelets & get_current_lanes() const
{
  return common_data_ptr_->lanes_ptr->current;
}

void NormalLaneChange::set_stop_pose(
  const double arc_length_to_stop_pose, PathWithLaneId & path, const std::string & reason)
{
  const auto stop_point = utils::insertStopPoint(arc_length_to_stop_pose, path);
  lane_change_stop_pose_ = PoseWithDetailOpt(PoseWithDetail(stop_point.point.pose, reason));
}

PathPointWithLaneId insertStopPoint(const double length, PathWithLaneId & path)
{
  const size_t original_size = path.points.size();

  // insert stop point
  const auto insert_idx = autoware::motion_utils::insertStopPoint(length, path.points);
  if (!insert_idx) {
    return PathPointWithLaneId();
  }

  // check if a stop point is inserted
  if (path.points.size() == original_size) {
    return path.points.at(*insert_idx);
  }

  if (*insert_idx == 0 || *insert_idx == original_size - 1) {
    return path.points.at(*insert_idx);
  }

  // check lane ids of the inserted stop point
  path.points.at(*insert_idx).lane_ids = {};
  const auto & prev_lane_ids = path.points.at(*insert_idx - 1).lane_ids;
  const auto & next_lane_ids = path.points.at(*insert_idx + 1).lane_ids;

  for (const auto target_lane_id : prev_lane_ids) {
    if (
      std::find(next_lane_ids.begin(), next_lane_ids.end(), target_lane_id) !=
      next_lane_ids.end()) {
      path.points.at(*insert_idx).lane_ids.push_back(target_lane_id);
    }
  }

  // If there is no lane ids, we are going to insert prev lane ids
  if (path.points.at(*insert_idx).lane_ids.empty()) {
    path.points.at(*insert_idx).lane_ids = prev_lane_ids;
  }

  return path.points.at(*insert_idx);
}

