double calcRssDistance(
  const double front_object_velocity, const double rear_object_velocity,
  const RSSparams & rss_params)
{
  const auto stoppingDistance = [](const auto vehicle_velocity, const auto vehicle_accel) {
    // compensate if user accidentally set the deceleration to some positive value
    const auto deceleration = (vehicle_accel < -1e-3) ? vehicle_accel : -1.0;
    return -std::pow(vehicle_velocity, 2) / (2.0 * deceleration);
  };

  const double & reaction_time =
    rss_params.rear_vehicle_reaction_time + rss_params.rear_vehicle_safety_time_margin;

  const double front_object_stop_length =
    stoppingDistance(front_object_velocity, rss_params.front_vehicle_deceleration);
  const double rear_object_stop_length =
    rear_object_velocity * reaction_time +
    stoppingDistance(rear_object_velocity, rss_params.rear_vehicle_deceleration);
  return rear_object_stop_length - front_object_stop_length;
}

bool has_blocking_target_object(
  const TargetLaneLeadingObjects & target_leading_objects, const double stop_arc_length,
  const PathWithLaneId & path)
{
  return ranges::any_of(target_leading_objects.stopped, [&](const auto & object) {
    const auto arc_length_to_target_lane_obj = motion_utils::calcSignedArcLength(
      path.points, path.points.front().point.pose.position, object.initial_pose.position);
    const auto width_margin = object.shape.dimensions.x / 2;
    return (arc_length_to_target_lane_obj - width_margin) >= stop_arc_length;
  });
}

double calcSignedArcLength(
  const T & points, const geometry_msgs::msg::Point & src_point,
  const geometry_msgs::msg::Point & dst_point)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  const size_t src_seg_idx = findNearestSegmentIndex(points, src_point);
  const size_t dst_seg_idx = findNearestSegmentIndex(points, dst_point);

  const double signed_length_on_traj = calcSignedArcLength(points, src_seg_idx, dst_seg_idx);
  const double signed_length_src_offset =
    calcLongitudinalOffsetToSegment(points, src_seg_idx, src_point);
  const double signed_length_dst_offset =
    calcLongitudinalOffsetToSegment(points, dst_seg_idx, dst_point);

  return signed_length_on_traj - signed_length_src_offset + signed_length_dst_offset;
}

