Direction getDirection() const
{
  if (direction_ == Direction::NONE && !status_.lane_change_path.path.points.empty()) {
    const auto lateral_shift = utils::lane_change::getLateralShift(status_.lane_change_path);
    return lateral_shift > 0.0 ? Direction::LEFT : Direction::RIGHT;
  }

  return direction_;
}

double getLateralShift(const LaneChangePath & path)
{
  if (path.shifted_path.shift_length.empty()) {
    return 0.0;
  }

  const auto start_idx =
    std::min(path.info.shift_line.start_idx, path.shifted_path.shift_length.size() - 1);
  const auto end_idx =
    std::min(path.info.shift_line.end_idx, path.shifted_path.shift_length.size() - 1);

  return path.shifted_path.shift_length.at(end_idx) - path.shifted_path.shift_length.at(start_idx);
}

void add(
  const double distance, const Pose & control_point_pose, const uint16_t behavior,
  const SafetyFactorArray & safety_factors, const bool is_driving_forward = true,
  const double velocity = 0.0, const double shift_length = 0.0, const std::string & detail = "")
{
  const auto control_point = autoware_internal_planning_msgs::build<ControlPoint>()
                               .pose(control_point_pose)
                               .velocity(velocity)
                               .shift_length(shift_length)
                               .distance(distance);

  const auto factor = autoware_internal_planning_msgs::build<PlanningFactor>()
                        .module(name_)
                        .is_driving_forward(is_driving_forward)
                        .control_points({control_point})
                        .behavior(behavior)
                        .detail(detail)
                        .safety_factors(safety_factors);

  factors_.push_back(factor);
}

